DROP TABLE IF EXISTS `value_table`;
CREATE TABLE `value_table`  (
  `value_id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `data_id` bigint UNSIGNED NOT NULL,
  `property_id` bigint UNSIGNED NOT NULL,
  `property_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `value` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  PRIMARY KEY (`value_id`) USING BTREE,
  UNIQUE INDEX `uk_data_property`(`data_id` ASC, `property_id` ASC) USING BTREE,
  INDEX `idx_property_id`(`property_id` ASC) USING BTREE,
  INDEX `idx_value_table_property_value_data`(`property_id` ASC, `value`(191) ASC, `data_id` ASC) USING BTREE,
  INDEX `idx_value_table_property_data_id`(`property_id` ASC, `data_id` ASC) USING BTREE,
  INDEX `idx_value_table_data_property_id`(`data_id` ASC, `property_id` ASC) USING BTREE,
  CONSTRAINT `fk_value_data_id` FOREIGN KEY (`data_id`) REFERENCES `entity_table` (`data_id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_value_property_id` FOREIGN KEY (`property_id`) REFERENCES `property_table` (`property_id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 31059 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci ROW_FORMAT = DYNAMIC;

