DROP TRIGGER IF EXISTS `trg_value_table_bi_set_property_name`;
delimiter ;;
CREATE TRIGGER `trg_value_table_bi_set_property_name` BEFORE INSERT ON `value_table` FOR EACH ROW SET NEW.property_name = (SELECT p.property_name FROM property_table p WHERE p.property_id = NEW.property_id)
;;
