INSERT INTO `value_table` VALUES (28141, 4042483, 17, 'production_process', '7003铝合金的热处理由固溶及时效两个步骤组成；时效处理分为3种时效制度：峰时效PA、双峰时效DPA及回归再时效RRA。PA：470℃×2h+120℃×50h；DPA：470℃×2h+120℃×120h；RRA：470℃×2h+120℃×48h+205℃×10min+120℃×48h');
